import numpy as np, itertools
D1=np.array([[9,9,4,4,8,8],[4,8,8,8,8,9],[4,5,5,5,8,5],[4,5,5,3,8,9],[1,1,1,1,8,1],[9,9,3,3,3,3]])
O1=np.array([[1,1,8,1,1,1],[3,3,3,3,9,9],[4,4,8,8,9,9],[8,8,8,9,4,8],[5,5,8,5,4,5],[5,3,8,9,4,5]])
D2=np.array([[4,5,1,1,4,4],[3,8,3,9,4,5],[5,8,5,5,5,5],[5,8,3,3,3,8],[5,5,1,1,5,5],[4,9,9,9,9,9]])
O2=np.array([[4,5,3,8,3,9],[5,5,5,8,5,5],[3,8,5,8,3,3],[5,5,5,5,1,1],[9,9,4,9,9,9],[4,4,4,5,1,1]])
def shiftrow(x,n): return np.roll(x,-n)
def vm(a,b): return np.sum(a==b)
for D,O in [(D1,O1),(D2,O2)]:
    # infer source rows and shifts
    print('case')
    for o in O:
        opts=[]
        for i,r in enumerate(D):
            for s in range(6):
                if np.array_equal(shiftrow(r,s),o):opts.append((i,s))
        print(opts)
    # per adjacent output source rows shifts maximizing matches
    print('max pair matches')
    pairs=[0,1,2,3,4,5]
    for a,b in zip(pairs[:-1],pairs[1:]):
        vals=[(vm(shiftrow(D[a],sa),shiftrow(D[b],sb)),sa,sb) for sa in range(6) for sb in range(6)]
        print(a,b,sorted(vals,reverse=True)[:5])
